<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Visualizer</title>
<style>
  :root { --bg: #14161c; --fg: #e6e8ee; --bar: #4a90e2; --acc: #f5a623; }
  * { box-sizing: border-box; }
  body {
    margin: 0; background: var(--bg); color: var(--fg);
    font-family: system-ui, sans-serif; min-height: 100vh;
    display: flex; flex-direction: column; align-items: center;
  }
  h1 { font-weight: 600; font-size: 1.3rem; margin: 20px 0 10px; }
  #controls { display: flex; gap: 10px; margin-bottom: 20px; }
  button {
    background: #232733; color: var(--fg); border: 1px solid #333a4a;
    padding: 8px 18px; border-radius: 6px; cursor: pointer; font-size: 0.95rem;
    transition: background .15s;
  }
  button:hover { background: #2e3648; }
  #bars {
    display: flex; align-items: flex-end; gap: 2px;
    width: 90vw; max-width: 900px; height: 420px;
    padding: 8px; background: #0f1116; border-radius: 8px;
    border: 1px solid #232733;
  }
  .bar {
    flex: 1 1 0; background: var(--bar); border-radius: 2px 2px 0 0;
    transition: height .05s linear, background .05s;
  }
  .bar.active { background: var(--acc); }
</style>
</head>
<body>
  <h1>Sorting Visualizer</h1>
  <div id="controls">
    <button id="sort">Sort</button>
    <button id="shuffle">Shuffle</button>
    <button id="reset">Reset</button>
  </div>
  <div id="bars"></div>

<script>
(function () {
  const barsEl = document.getElementById('bars');
  const N = 40;
  let arr = [];
  let initial = [];

  // Sorting state (insertion sort, one step at a time)
  let i = 1, j = 0, sorting = false, done = false;

  function makeInitial() {
    const a = [];
    for (let k = 0; k < N; k++) a.push(Math.floor(Math.random() * 290) + 10);
    return a;
  }

  function render(activeIdx) {
    barsEl.innerHTML = '';
    const max = Math.max(1, ...arr);
    for (let k = 0; k < arr.length; k++) {
      const b = document.createElement('div');
      b.className = 'bar' + (activeIdx != null && (k === activeIdx || k === activeIdx - 1) ? ' active' : '');
      b.style.height = (arr[k] / max * 100) + '%';
      barsEl.appendChild(b);
    }
  }

  function resetSortState() {
    i = 1; j = 0; done = arr.length <= 1;
  }

  function isSorted() {
    for (let k = 1; k < arr.length; k++) if (arr[k - 1] > arr[k]) return false;
    return true;
  }

  // Perform exactly one comparison/step of insertion sort.
  function sortStep() {
    if (done || arr.length <= 1) { done = true; render(); return true; }
    if (i >= arr.length) { done = true; render(); return true; }

    if (j > 0 && arr[j - 1] > arr[j]) {
      const t = arr[j]; arr[j] = arr[j - 1]; arr[j - 1] = t;
      j--;
    } else {
      i++;
      j = i;
    }

    if (i >= arr.length) done = true;
    render(j);
    return done;
  }

  // ---- animation loop ----
  let raf = null;
  function animate() {
    if (sortStep()) { sorting = false; raf = null; render(); return; }
    raf = requestAnimationFrame(animate);
  }

  function startSort() {
    if (sorting) return;
    if (isSorted()) { done = true; return; }
    sorting = true;
    if (done) resetSortState();
    animate();
  }

  function stopSort() {
    sorting = false;
    if (raf) { cancelAnimationFrame(raf); raf = null; }
  }

  function shuffle() {
    stopSort();
    for (let k = arr.length - 1; k > 0; k--) {
      const r = Math.floor(Math.random() * (k + 1));
      const t = arr[k]; arr[k] = arr[r]; arr[r] = t;
    }
    resetSortState();
    render();
  }

  function reset() {
    stopSort();
    arr = initial.slice();
    resetSortState();
    render();
  }

  document.getElementById('sort').addEventListener('click', startSort);
  document.getElementById('shuffle').addEventListener('click', shuffle);
  document.getElementById('reset').addEventListener('click', reset);

  // Public API
  window.viz = {
    array() { return arr.slice(); },
    setArray(a) {
      stopSort();
      arr = Array.from(a, Number);
      initial = arr.slice();
      resetSortState();
      render();
    },
    sortStep() { return sortStep(); },
    sorted() { return isSorted(); },
  };

  // init
  initial = makeInitial();
  arr = initial.slice();
  resetSortState();
  render();
})();
</script>
</body>
</html>
